'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-plain-object' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var isPositiveInteger = require( '@stdlib/assert/is-positive-integer' ).isPrimitive;
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Validates function options.
*
* @private
* @param {Object} opts - destination object
* @param {Options} options - function options
* @param {NonNegativeInteger} [options.indent] - number of leading spaces per output line
* @param {PositiveInteger} [options.maxWidth] - total line width limit
* @returns {(Error|null)} error object or null
*
* @example
* var opts = {};
* var options = {
*     'indent': 4,
*     'maxWidth': 80
* };
*
* var err = validate( opts, options );
* if ( err ) {
*     throw err;
* }
*/
function validate( opts, options ) {
	if ( !isObject( options ) ) {
		return new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	if ( hasOwnProp( options, 'indent' ) ) {
		opts.indent = options.indent;
		if ( !isNonNegativeInteger( opts.indent ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a nonnegative integer. Option: `%s`.', 'indent', opts.indent ) );
		}
	}
	if ( hasOwnProp( options, 'maxWidth' ) ) {
		opts.maxWidth = options.maxWidth;
		if ( !isPositiveInteger( opts.maxWidth ) ) {
			return new TypeError( format( 'invalid option. `%s` option must be a positive integer. Option: `%s`.', 'maxWidth', opts.maxWidth ) );
		}
	}
	return null;
}


// EXPORTS //

module.exports = validate;
